+			end := start + 512
+			if end > len(j.Rows) {
+				end = len(j.Rows)
+			}
+			if err := db.Exec(j.InsertBulk, map[string]any{"rows": j.Rows[start:end]}); err != nil {
+				return nil, fmt.Errorf("setup: %w", err)
+			}
+		}
+	}
