+	if j.CPUProfile != "" {
+		file, err := os.Create(j.CPUProfile)
+		if err != nil {
+			return nil, err
+		}
+		defer file.Close()
+		if err := pprof.StartCPUProfile(file); err != nil {
+			return nil, err
+		}
+		defer pprof.StopCPUProfile()
+	}
+	runtime.ReadMemStats(&before)
