+			called := time.Now()
+			err := db.Exec(j.InsertSingle, row)
+			queryNS += time.Since(called).Nanoseconds()
+			if err != nil {
+				return nil, fmt.Errorf("execute: %w", err)
+			}
+		}
+	} else if j.Case == "fill_bulk" {
+		called := time.Now()
+		err := db.Exec(j.InsertBulk, map[string]any{"rows": j.Rows})
+		queryNS += time.Since(called).Nanoseconds()
+		if err != nil {
+			return nil, fmt.Errorf("execute: %w", err)
+		}
+	}
+	writeNS := queryNS
+	calls := 1
+	if j.Case == "point" {
+		calls = len(j.Rows)
+	}
+	for i := 0; i < calls; i++ {
+		text := j.Scan
+		var params map[string]any
+		if j.Case == "point" {
+			text = j.Point
+			params = map[string]any{"id": j.Rows[i]["id"]}
+		}
+		called := time.Now()
+		output, err := db.Query(text, params)
+		queryNS += time.Since(called).Nanoseconds()
+		if err != nil {
+			return nil, fmt.Errorf("execute: %w", err)
+		}
+		if len(output.Columns) != len(j.Columns) {
+			return nil, fmt.Errorf("consumer: schema mismatch")
+		}
+		for k := range j.Columns {
+			if output.Columns[k] != j.Columns[k] {
+				return nil, fmt.Errorf("consumer: schema mismatch")
+			}
+		}
+		consumed := time.Now()
+		for _, values := range output.Rows {
+			c.bytes([]byte{0xff})
+			c.length(uint64(len(values)))
+			for _, value := range values {
+				c.value(value)
+			}
+			rowsSeen++
+		}
+		consumeNS += time.Since(consumed).Nanoseconds()
+	}
+	elapsedNS := time.Since(started).Nanoseconds()
+	var profile map[string]any
+	if nativeRead != nil {
+		nativeRead(&nativeAfter)
+		profile = profileDelta(nativeBefore, nativeAfter)
+	}
+	if hostProfiling {
+		hostAfter = hostRead()
+	}
+	runtime.ReadMemStats(&after)
+	report = map[string]any{"status": "ok", "layer": "go", "case": j.Case, "backend": j.Backend, "input_rows": len(j.Rows), "output_rows": rowsSeen, "values": rowsSeen * len(j.Columns), "checksum": fmt.Sprintf("%016x", uint64(c)), "setup_ns": setupNS, "query_boundary_ns": queryNS, "write_boundary_ns": writeNS, "read_boundary_ns": queryNS - writeNS, "consumer_ns": consumeNS, "elapsed_ns": elapsedNS, "go_allocations": after.Mallocs - before.Mallocs, "go_allocated_bytes": after.TotalAlloc - before.TotalAlloc, "native_profile": profile, "cpu_profile": j.CPUProfile, "durability": "SyncOnEveryWrite", "cgo_enabled": false}
